// Copies the design tokens generated by portico-theme into this site.
// Usage: npm run sync-tokens [path/to/Portico]   (default: ../Portico)
import { copyFileSync, existsSync } from 'node:fs';
import { resolve } from 'node:path';

const repo = resolve(process.argv[2] ?? '../Portico');
const src = resolve(repo, 'apps/portico-gui/src/lib/styles/tokens.css');
if (!existsSync(src)) {
  console.error(`tokens.css not found at ${src}: run \`cargo run -p portico-theme --bin export-tokens\` in Portico first`);
  process.exit(1);
}
copyFileSync(src, resolve('src/styles/tokens.css'));
console.log(`synced ${src}`);
